<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Http\Response;

class AgentSpecificationController extends Controller
{
    public function show(Request $request): Response
    {
        $agent = $request->user();
        $abilities = collect($agent->currentAccessToken()?->abilities ?? [])->sort()->values();
        $memberships = $agent->scopeMemberships()
            ->where('is_active', true)
            ->with('scope:id,name,slug')
            ->orderBy('scope_id')
            ->get();
        $language = match ($agent->preferred_language) {
            'en' => ['English', 'Write task comments, durable notes, reports, and user-facing answers in English unless the task explicitly requires another language.'],
            'zh' => ['Chinese', 'Write task comments, durable notes, reports, and user-facing answers in Chinese unless the task explicitly requires another language.'],
            default => ['Russian', 'Write task comments, durable notes, reports, and user-facing answers in Russian unless the task explicitly requires another language.'],
        };

        $scopeLines = $memberships->map(function ($membership): string {
            $scope = $membership->scope;

            return sprintf(
                '- `%s` — %s; role `%s`; project access `%s`',
                $scope->id,
                $scope->name,
                $membership->role,
                $membership->project_access_mode,
            );
        });

        $lines = [
            '# Zuratax Agent API',
            '',
            'Specification version: 2026-10-25.2',
            'Generated at: '.now()->toIso8601String(),
            '',
            '## Identity and access',
            '',
            "You are authenticated as **{$agent->name}** (`{$agent->id}`).",
            "Working language: **{$language[0]}** (`{$agent->preferred_language}`).",
            $language[1],
            'Token abilities: '.($abilities->isEmpty() ? '_none_' : $abilities->map(fn (string $ability): string => "`{$ability}`")->implode(', ')).'.',
            '',
            'Accessible scopes:',
            ...($scopeLines->isEmpty() ? ['- _none_'] : $scopeLines->all()),
            '',
            '## Transport contract',
            '',
            '- Use HTTPS and send the token only as `Authorization: Bearer <token>`.',
            '- Send `Accept: application/json` for API data and `Content-Type: application/json` for POST/PATCH requests, except Filer uploads: use multipart/form-data and let your HTTP library generate the boundary.',
            '- Never put the token in a URL, task text, comment, log, commit, or chat message.',
            '- Treat `401` as an invalid/revoked token, `403` as a scope/capability boundary, and `422` as a validation error.',
            '- Follow pagination links/meta where a collection is paginated.',
            '- Use task keys such as `ADM-154` when talking to people; use entity IDs in API paths and payloads.',
            '',
            '## Discovery and work queue',
            '',
            '- `GET /api/agent/spec` — fetch this current specification before starting work.',
            '- `GET /api/agent/me` — verify the account.',
            '- `GET /api/agent/scopes` — list accessible scopes.',
            '- `GET /api/agent/tasks` — personal delegated queue. Add `?include_closed=1` to include done and cancelled tasks.',
            '',
            'The personal queue only contains tasks explicitly delegated to this agent and marked as agent-delegatable. Do not infer access from a task mentioned elsewhere.',
            '',
            '## Diagrams API',
            '',
            'Local draw.io diagrams live in Content, independently of Booker. Base path: `/api/agent/scopes/{scope}/diagrams`. Requires task.view, active scope membership and project/privacy access. No diagram is uploaded to an external editor.',
            '- GET /: paginated readable metadata (30 per page); filters q, project_id, page, subject_type + subject_id. Response {data: [...], meta: {page, has_more}}; XML/previews are only in GET /{diagram}. Follow has_more.',
            '- GET /options: available projects and can_create. GET /targets?type=task&q=...: attachment candidates.',
            '- POST /: {title, description?, project_id?, visibility?: private|scope, allow_member_editing?: boolean, xml?, preview_svg?}. Defaults to a private empty diagram with member editing disabled. Requires task.create; returns 201.',
            '- PATCH /{diagram}: partial fields plus REQUIRED revision from last GET. Requires task.update and can_edit=true from the full GET. By default only the creator/scope owner can edit; allow_member_editing=true also permits readable project/scope members with write access. Existing privacy, project restrictions, denied capabilities and agent-token abilities still apply. Only managers (can_manage=true) may change visibility, project_id or allow_member_editing, attach/detach, manage navigation or delete. Full GET includes can_edit, can_manage and can_delete.',
            '- XML is full draw.io mxfile/mxGraphModel (all pages), max 5 MiB, no DOCTYPE/entities. An XML-only update clears the old preview. Missing fields stay unchanged. A stale revision returns 409: re-read, reconcile, never blindly overwrite.',
            '- POST /{diagram}/duplicate: optional {title}; requires task.create. Creates an independent private copy at revision 1, without source attachments/history.',
            '- GET /{diagram}/revisions and GET /{diagram}/revisions/{revision}: up to the latest 100 saved versions; same privacy as current diagram. DELETE /{diagram} soft-deletes with task.delete plus management access.',
            '- POST /{diagram}/attachments: {subject_type, subject_id}. Types: task, project, book, book_page, event, lore, darklog, fact, plan_item, file, user. Requires diagram management and target write access; completed/deleted tasks cannot be changed. Plans additionally require report.view/report.write, books require book access, people require contractor management (or self). DELETE /{diagram}/attachments/{attachment} removes only that link.',
            '- Linking never grants diagram access and never copies XML. Permalink: /content/diagrams/{scope}/{diagram}. Previews are untrusted SVG: use an image, never inject as HTML.',
            '',
            '## Document graph browser API',
            '',
            'Base: `/api/agent/scopes/{scope}/content-nodes`. Supported node types: diagram, file, lore, task, lightbook. Traversal is a directed graph, NOT a parent tree; cycles and self-links are valid. Breadcrumbs represent visits. Navigation never changes diagram XML or creates diagram versions.',
            '- GET /{type}/{id}: {data: {type,id,title,code,document,can_manage,can_edit,links}}. can_edit is diagram content-edit permission, distinct from navigation management. Full simplified document and immediate outgoing links only. Each source and target is independently authorized using its native module privacy/project rules and token abilities. Missing, deleted and inaccessible nodes return 404; inaccessible targets and their labels are omitted. Linking never grants access.',
            '- GET /targets?type=diagram&q=...&page=1: authorized candidates, 30 per page, {data,meta:{page,has_more}}. Follow has_more.',
            '- POST /{type}/{id}/links creates (201); PATCH /{type}/{id}/links/{link} replaces (200): {target_type,target_id,label?:string|null,region?:null|{page_id,x,y,width,height},source_revision?:integer}. IDs are ULIDs. Labels max 160. Region is only valid on a diagram, uses normalized SVG content bounds with 5% overscan (-0.05..1.05), positive width/height, must fit inside that extended page, and requires the exact current diagram revision. 409 means stale diagram: re-read and recheck/re-draw the region, never blindly resubmit.',
            '- DELETE /{type}/{id}/links/{link} soft-deletes only the navigation edge (204), never the target. All writes require source management permission and are audited. Frozen tasks cannot be changed. Maximum 500 outgoing links per source. All endpoints are limited to 90 requests/minute.',
            '',
            '## Filer API',
            '',
            'File metadata includes optional plain-text description. PATCH /api/agent/scopes/{scope}/files/{file} accepts only {description: string|null} (maximum 2000 characters); requires task.update plus file management access. Upload does not require a description.',
            'Office preview: POST /api/agent/scopes/{scope}/files/{file}/preview queues a PDF copy (read permission suffices); GET on the same URL polls {data:{status}} (idle, pending, ready, failed, unavailable, unsupported). Poll at most once per 3 seconds, stop after 2 minutes and report pending instead of retrying forever. GET /api/agent/scopes/{scope}/files/{file}/preview/content downloads the ready PDF with the same ACL as the original. On failed, retry only explicitly. This does not edit the original. Word/Excel/ODF conversion is local, no third-party upload.',
            '',
            'Base path: `/api/agent/scopes/{scope}/files`. Requires active scope membership and `task.view` in both account permissions and token abilities. Existing subject/project/book privacy checks always apply.',
            '- `GET /`: list readable files; filters `category`, `q`, `subject_type` + `subject_id`, `page`. Response `{data: [...], meta: {page, has_more}}`, up to 30 per page.',
            '- `GET /targets?type=task&q=...`: up to 50 writable attachment targets; requires `task.update`. Types: task, event, book, project, user, darklog.',
            '- `POST /`: upload multipart fields `file` (maximum 20 MiB), `category`, `visibility` (private or scope), optional `subject_type` and `subject_id`. Categories: documentation, general, task, event, book, project, user, darklog. Module categories require a matching target. Requires `task.update` and write access to the target (including `book.update` for books). Returns 201 with `{data: file}`.',
            '- `GET /{file}/download`: binary attachment, not JSON. Keep the Bearer key in the header, never the URL.',
            '- `POST /{file}/attachments`: JSON `subject_type`, `subject_id`; requires `task.update`, ownership (or scope owner), and write access to every existing and new target.',
            '- `DELETE /{file}`: permanently removes physical content and ALL attachment links; requires `task.update`, `task.delete`, ownership (or scope owner), and write access to every target. Returns 204. Only delete when explicitly authorized by the user.',
            '- Private files are author-only, even for scope owners. Scope files require access to ALL linked subjects; linking to a public task does not expose a private book attachment. `can_manage` describes ownership/subject write access; route token abilities are required additionally.',
            '- 401: revoked/invalid key; 403: insufficient permission; 404: absent or inaccessible file/target; 413/422: invalid or oversized upload; 507: insufficient disk space. Do not retry forbidden operations or disk-full uploads blindly.',
            '',
            '## Photos and image attachments',
            '',
            '- Work with files/photos only as needed for the user-assigned task. Do not send private attachments to third-party conversion or analysis services without permission.',
            '- Use the Filer endpoints above. Add `photos=1` to the file list to select JPEG/PNG/WebP images, combined with subject filters when needed.',
            '- Upload multipart `photo=1` with a JPEG, PNG, or WebP file (20 MiB and 24 megapixels maximum). The server corrects JPEG orientation and stores a compressed WebP with a maximum dimension of 2000 px (512 px for user photos), without upscaling. The original is NOT retained. Omit `photo` to preserve the original as a regular file.',
            '- `GET /api/agent/scopes/{scope}/files/{file}/image`: binary inline raster image, not JSON; requires `task.view` and file access. Authenticate with the Bearer header. Use `/download` for original file attachments; neither endpoint is a public URL.',
            '- Attach photos to tasks, events, books, projects, users or darklogs using `subject_type` and `subject_id`. For event galleries upload each image separately. Discover writable targets through `/files/targets?type=event` (or another supported type).',
            '- `POST /api/agent/scopes/{scope}/files/{file}/feature`: JSON `{ "subject_type": "event", "subject_id": "<event-ulid>", "enabled": true }` selects an event cover. Use `subject_type=user` for an avatar. `enabled=false` clears the target cover/avatar. Returns 204.',
            '- Selecting a cover/avatar requires `task.update`, read access to the file and write access to the target. The raster photo must have `visibility=scope` and already be attached to that target. An avatar must be a dedicated photo with exactly one attachment. Managing another user additionally requires the appropriate contractor management permission.',
            '- A selected scope-visible avatar can be read through `/image` by colleagues in that scope. This does not make other profile attachments readable and does not grant `/download` access.',
            '- A Booker photo block has type `photo` and payload `{ "scope_id": "<scope-ulid>", "file_id": "<file-ulid>", "caption": "Optional caption" }`. Upload to the book first; normal book access and editing-lock rules still apply when editing blocks. Store file IDs, not Bearer URLs or base64. Physical file deletion can break references in old book versions.',
            '- Booker editing workflow: `POST /api/agent/scopes/{scope}/books/{book}/pages/{page}/editing` acquires the lock (423 means another editor owns it). Create a block via POST to `/blocks`; update an existing block via POST to `/blocks/{group}/versions`. When done, DELETE `/editing` releases the lock. Do not call POST `/editing/cancel` unless explicitly asked to roll back the whole editing session.',
            '',
            '## Planner: monthly plan items (not calendar tails)',
            '',
            'Base path: `/api/agent/scopes/{scope}/plans`. Reads require BOTH `report.view` and `task.view`; writes additionally require BOTH `report.write` and `task.update`, in token abilities and account permissions. Project restrictions and private-project visibility apply. Existing keys do not acquire missing abilities automatically; ask the owner to issue an appropriately scoped key.',
            '- `GET /?year=2026`: year is required (2000–2099); optional `month=2026-10`, `project_id`, `assignee_id`, `status=open|done`, `q`, `page`. Returns `{data:{items:[],total,done,page,last_page}}`, 40 items per page. Fetch subsequent pages through `last_page`.',
            '- `GET /options`: returns `{data:{projects:[],people:[]}}` for accessible projects and scoped real/virtual executors. Assignee access to the chosen project is revalidated on save.',
            '- `GET /candidates?project_id=<project-ulid>&q=...`: selectable tasks, 30 per page, with standard `data`, `links`, `meta` pagination. Omit `project_id` for unprojected tasks, not all projects. Each task includes `linked_plans` with accessible plan IDs, titles, and months; reuse in multiple plans is allowed.',
            '- `GET /{planItem}`: one accessible plan under `data`, with tasks, `tasks_count`, `completed_tasks_count`, project, assignee, and completion information.',
            '- `POST /`: required `title` (max 255) and `month` (`YYYY-MM`, 2000–2099). Optional nullable `project_id`, `assignee_id`, `description` (max 20000), `resources`, `expected_result`, `impact`, `actual_result` (each max 10000), `starts_on`, `ends_on` (`YYYY-MM-DD`), `estimated_minutes` (0–525600); optional `priority` (1–5), `completed` (boolean), `task_ids` (up to 500 distinct task ULIDs), `task_dates` (object mapping task ULIDs to YYYY-MM-DD calendar dates). Each linked task must have a main calendar date in the plan month; provide task_dates to schedule or reschedule it atomically. Returns 200 with `{data: plan}`.',
            '- `PATCH /{planItem}`: same editable fields; omitted fields are preserved. `task_ids` replaces the entire task selection; `[]` clears it. Tasks must be accessible and belong to the same scope and project as the plan. For a project change, explicitly remove or replace old task links in the same request. Dates must be ordered.',
            '- Completion is explicit: PATCH `{ "completed": true, "actual_result": "Verified outcome" }`; `{ "completed": false }` reopens. A plan can be completed without linked tasks. This does NOT complete tasks, create calendar entries, or move calendar tails.',
            '- `DELETE /{planItem}`: soft-delete the plan only, preserving tasks; returns 204. Only call when explicitly authorized by the user.',
            '- Requests leave agent API audit traces; plan changes also record domain history. Plan writes and photo/file operations are limited to 60 requests per minute per group; respect 429 and Retry-After.',
            '',
            'Minimal plan example (POST to the plans base path):',
            '```json',
            '{"title":"Improve reservation workflow","month":"2026-10","project_id":"<project-ulid>","expected_result":"Verified reservation scenarios","task_ids":["<task-ulid>"],"task_dates":{"<task-ulid>":"2026-10-15"}}',
            '```',
            '',
            '## Darklog: problems, constraints and external influences',
            '',
            'Base: `/api/agent/scopes/{scope}/darklogs`. These records describe adverse influences, not guilt. `responsible_id` is the maintainer, never an automatically assigned culprit. All reads and links respect scope/project/privacy restrictions. Capabilities: `task.view` to read, `task.create` to create, `task.update` to edit/comment/link, `task.delete` to soft-delete. Token abilities and account permissions must both allow the action.',
            '- `GET ?month=2026-10&timezone=Europe/Moscow`: paginated `{data:{items,total,page,last_page,from,until}}`; filters `status` (including `active`), `project_id`, `department_id`, `responsible_id`, `severity`, `kind`, `q`, `page`, `per_page` (1..100). Period intersection is half-open: [start,end).',
            '- `GET ?month=2026-10&subject_type=task&subject_id={id}`: visible Darklogs linked to that readable record, across all months. A hidden target returns 404.',
            '- `GET /options`: permitted projects, departments, people, KPIs and action flags. `GET /candidates?type=task&q=WMS`: readable link targets (up to 30).',
            '- `GET /{darklog}`: full card, periods, links, KPI applicability and chronological timeline. Browser permalink: `/darklog/{scope}/{darklog}`. Codes `DRK-42` are unique within a scope, not globally.',
            '- `POST` creates a record; `PATCH /{darklog}` updates only supplied fields. Minimum create payload: `{"title":"Network outage","origin":"external","periods":[{"starts_at":"2026-10-15T09:00:00Z","ends_at":null}]}`. Times must include timezone; use UTC ISO 8601.',
            '- Markdown fields: `description`, `impact`, `workaround`, `resolution`. Optional `project_id`, `department_id`, `responsible_id`, `category`, `expected_end_at`, `decision_reason`. A responsible maintainer must be a real or virtual human in the scope; agent accounts cannot be assigned. Agents may still create records and comments within their capabilities. Kinds: `incident|constraint|external_factor|regression`; origins: `internal|external|systemic|unknown`; severities: `low|medium|high|critical`; statuses: `new|investigating|working|waiting|monitoring|closed|accepted|unconfirmed`.',
            '- `periods` replaces the entire set ONLY when supplied: retain existing period `id` to edit it, omit id to add, omit a previous period to remove it. Actual starts/ends cannot be in the future, end must follow start, periods cannot overlap. Null end is ongoing. `expected_end_at` is a forecast, not actual closure. `closed` requires ended periods; `accepted|unconfirmed` requires `decision_reason`.',
            '- `POST /{darklog}/links`: `{target_type,target_id,relation,note?}`; `DELETE /{darklog}/links/{link}`. Types: `task,event,project,book,book_page,fact,lore,plan_item,darklog,file`. Roles: `possible_cause,confirmed_cause,affected,remediation,context,duplicate`. A completed task can be linked without modifying its frozen content.',
            '- `POST /{darklog}/comments`: `{content,parent_id?}`; one reply level. `DELETE /{darklog}/comments/{comment}`: author or contractor manager. Comments support Markdown.',
            '- `POST /{darklog}/kpi`: `{user_id,kpi_id,decision,reason?,effective_from,effective_until?}`. Decisions: `pending|included|excluded`. Only contractor managers can confirm/exclude or remove via `DELETE /{darklog}/kpi/{allocation}`; non-pending decisions require a reason. Applicable person must be an active executor of this scope. This is manual applicability groundwork: NO automatic point deduction/award or responsibility contour matching yet.',
            '- Attach files/photos using the Filer API with `subject_type=darklog`, `subject_id={darklog}`, `category=darklog`. `DELETE /{darklog}` is a soft delete; audit history remains. Never treat forecasts, unreviewed links or a named maintainer as evidence of fault.',
            '',
            '## Lightbook API',
            '',
            'Lightbook is a standalone one-page document backed by the same block, editing-lock, version and comment engine as a Booker page. Base path: `/api/agent/scopes/{scope}/lightbooks`. It appears in Content and in the document graph as type `lightbook`.',
            '- Reads require `book.view`; create requires `book.create`; metadata/page/block/version changes require `book.update`; deletion requires `book.delete`. `book_access_mode` and project restrictions apply exactly as in Booker.',
            '- `GET /` lists readable Lightbooks; filters q, project_id, section_id, category_id. The three ID filters accept `none` to select unassigned records; omit them for all. A section filter includes readable descendants. `POST /` creates a Lightbook and its only page atomically; required `title`, optional `description`, `project_id`, `section_id`, `category_id`, `visibility`, `comments_enabled`, `version_depth`. `GET|PATCH|DELETE /{lightbook}` manage the document metadata. These three independent assignments are nullable; changing a section never changes the project or visibility.',
            '- The response contains `page_id` and `page`. Use `/lightbooks/{lightbook}/pages/{page}` for reading, editing locks, comments, versions and blocks with the same payloads and conflict rules as the Booker page endpoints below. Creating a second page is intentionally unsupported.',
            '- Graph read: `GET /api/agent/scopes/{scope}/content-nodes/lightbook/{lightbook}`. Link it from a diagram or another supported document with target_type `lightbook`; candidate discovery uses `/content-nodes/targets?type=lightbook&q=...`.',
            '',
            '## Shared content sections and categories',
            '',
            'Base: `/api/agent/scopes/{scope}/content-structure/{module}`, where module is `eventor` or `lightbook`. Both contexts use the SAME sections (existing Eventor section identities) and categories within the scope; they are NOT projects or project memberships. Modules must be enabled. Eventor requires task.view/create/update; Lightbook requires book.view/create/update and book access. Token denies and contractor boundaries always apply.',
            '- GET /: {data:{sections,categories,can_create}}. Each row includes revision and can_manage. Private section names are visible only to their creator or scope owner; descendants of inaccessible sections are omitted. Catalog metadata never grants record access. Record privacy and project/book restrictions are checked independently.',
            '- POST /sections or /categories: required name (max96), optional description (max255), color (#RRGGBB or #RRGGBBAA), sort_order (0..1000000), is_archived. Sections additionally accept nullable parent_id and visibility=private|scope|public (default scope). Categories are flat classification, NOT folders. One record can have one nullable section_id and one nullable category_id independently of its project_id.',
            '- PATCH /sections/{id} or /categories/{id}: partial fields plus REQUIRED revision from GET. DELETE on the same path: JSON {revision}. Only the creator/scope owner with update capability may manage a row. 409 means stale revision: re-read and reconcile. Cross-scope references and cycles are rejected. Section nesting under archived parents or making a child more visible than a private ancestor is rejected.',
            '- Nonempty sections/categories, including soft-deleted linked records or child sections, cannot be deleted (422). Archive them instead. Existing record assignments remain readable/editable when archived; new assignments to archived entries or descendants of archived sections are rejected. Archive does not delete or reclassify content.',
            '',
            '## Eventor API',
            '',
            'Base `/api/agent/scopes/{scope}/events`: GET / (paginated data/meta), POST /, GET|PATCH|DELETE /{event}. Reads require task.view, create task.create, changes/deletion task.update. Record privacy and project access remain mandatory. GET /event-types on the scope returns available types.',
            '- POST requires title; optional content (Markdown), project_id, section_id, category_id, type_id, starts_at, ends_at, occurred_at, visibility=private|scope|public, status=draft|published|archived. Project, section and category are independent nullable references, all inside this scope. PATCH sends only changed fields; missing fields remain unchanged.',
            '- GET / filters q, project_id, section_id, category_id, type_id, created_by, requester_id, importance, status, from, until, pinned. project_id/section_id/category_id accept `none`; a section includes its descendants, without bypassing privacy or project checks. GET /calendar requires from/until as YYYY-MM-DD (maximum93 days); optional timezone, same filters and pagination. Follow pages: recurring occurrences can span multiple pages.',
            '',
            '## Booker API',
            '',
            'Base path: `/api/agent/scopes/{scope}/books`. Booker stores structured books, page trees and versioned content blocks. Reads require `book.view`; creation requires `book.create`; book/page/block changes require `book.update`; deleting a whole book requires `book.delete`. Token abilities, membership permissions, `book_access_mode` and project access must all allow the action.',
            '- `GET /`: all readable books under `{data:[...]}` (not paginated). `GET /{book}` returns one book. Private books are creator-only; shared books still follow `book_access_mode=none|projects|all` and project restrictions.',
            '- `POST /`: required `title` (max 255). Optional `space_id`, `project_id`, `slug`, `description`, `visibility=private|scope|public`, `comments_enabled`, `cover_color`, `cover_svg_url`, `cover_svg_text`, `sort_order`. Returns 201. The project and space must belong to the scope and be accessible.',
            '- `PATCH /{book}`: partial book fields plus `structure_mode=tree|flat` and `version_depth=1..100`. Omitted fields stay unchanged. `scope_id` moves a book and clears its space/project; do this only when the assigned task explicitly requests a move and the agent belongs to the target scope.',
            '- `GET /{book}/pages`: complete ordered page list. `POST /{book}/pages`: required `title`; optional `parent_id`, `slug`, `visibility`, `sort_order`. `GET /{book}/pages/{page}` returns the page, editor, groups and active master blocks.',
            '- Before changing a page or its blocks, `POST /{book}/pages/{page}/editing`. The lock lasts 30 minutes and creates a page snapshot; 423 means another editor owns a fresh lock. `DELETE /editing` commits by releasing the lock. `POST /editing/cancel` restores the snapshot and removes that editing version; call cancel only when explicitly asked to discard the whole session.',
            '- `PATCH /{book}/pages/{page}` requires an editing lock owned by the caller and accepts partial `parent_id`, `title`, `slug`, `visibility`, `sort_order`. A page cannot parent itself and its parent must be in the same book.',
            '- `GET /{book}/pages/{page}/blocks`: ordered block groups with each current `master_block`. `POST /blocks` requires the editing lock and `type`; types: markdown, excalidraw, svg, photo, table, code, callout, checklist, divider, embed. Optional group fields: `role`, `visibility`, `sort_order`; initial version fields: `title`, `content`, `payload`, `search_text`. Returns 201.',
            '- `POST /blocks/{group}/versions` requires the editing lock and creates a new immutable block version from optional `title`, `content`, `payload`, `search_text`, `status=draft|published`; the new version becomes `master_block`. Missing values are not inherited automatically, so send the complete intended block content. Returns 201.',
            '- `POST /blocks/reorder`: `{items:[{id,sort_order}]}` with distinct group ULIDs and positive integer positions. Every item must belong to the page. `DELETE /blocks/{group}` requires the editing lock and soft-deletes that group; cancel can restore it from the session snapshot.',
            '- `GET /{book}/pages/{page}/versions` lists retained page snapshots; `GET /versions/{version}` returns one full snapshot. `POST /versions/{version}/restore` first snapshots the current page, then restores the selected version; it is rejected with 423 when another editor owns the page. Retention follows the book `version_depth`.',
            '- `GET|POST /{book}/pages/{page}/comments`: POST requires `content` (max 20000), optional `parent_id`, and `kind=comment|question|answer`; comments must be enabled. `DELETE /comments/{comment}` is allowed to its author, the book creator or the scope owner. Comment writes currently require readable book access, not the page editing lock.',
            '- `DELETE /{book}` soft-deletes the book and releases page locks; use only when the assigned task explicitly authorizes deletion. There is no agent endpoint for deleting individual pages.',
            '',
            '### Booker full import',
            '',
            '`POST /api/agent/scopes/{scope}/imports/booker` imports one complete historical book. It requires `book.create`, `book.update` and full scope book access (`book_access_mode=all` or scope owner). Always send `dry_run:true` first, inspect planned create/reuse counts, then resend the identical payload without dry_run.',
            '- Top level: `source` (stable lowercase identifier, max 64), optional `dry_run`, and arrays `pages` (max 1000), `groups` (max 5000), `blocks` (max 10000). `book.external_id` and every child external ID are ULIDs and are preserved for idempotency.',
            '- `book` requires `external_id,title,structure_mode,visibility,sort_order,is_archived,created_at,updated_at`; optional `slug,description,cover_color,cover_svg_url,cover_svg_text,export_settings,meta`. Imports are unprojected and not assigned to a Booker space.',
            '- Every page requires `external_id,title,visibility,sort_order,is_archived,created_at,updated_at`; optional `parent_external_id,slug,meta`. Every group requires `external_id,page_external_id,master_block_external_id,type,role,visibility,is_hidden_by_default,sort_order,created_at,updated_at`; optional `meta`.',
            '- Every block requires `external_id,group_external_id,version_number,status,created_at,updated_at`; status is draft, published or archived; optional `title,content,payload,published_at`. References must resolve within the same request.',
            '- Import never updates or deletes an existing entity. It reuses an ID only when that record was imported earlier from the same `source` into the same parent; collisions return 409. Fix the source data instead of generating replacement IDs after a collision.',
            '',
            '## Scope task API',
            '',
            '### Exploiter: equipment operation journal',
            '',
            '- Base: `/api/agent/scopes/{scope}/exploiter`. Both Equip and Exploiter must be enabled. Read requires `equip.view`; create, PATCH and soft DELETE require `equip.update`. Token abilities AND scope permissions apply; equipment department visibility is enforced for all endpoints and totals.',
            '- GET base: paginated journal (`data`, `meta.page`, `meta.last_page`, `meta.total`). Filters: `q`, `thing_id`, `department_id`, `kind`, `status`, `from`, `to`, `page`. Lists omit Markdown bodies; GET `/{entry}` returns the complete record.',
            '- GET `/options`: permitted departments, human assignees and effective Equip permissions. GET `/things?q=...`: existing visible Equip equipment; do not create duplicate inventory entities.',
            '- POST base requires existing `thing_id`, `kind`, `title`, `occurred_on` (YYYY-MM-DD). Kinds: `work|incident|inspection|consumption|reading|note`; statuses: `planned|in_progress|done|cancelled`; priorities: `low|normal|high|critical`.',
            '- Optional Markdown: `content_md`, `result_md`. Other fields: `performer_id` (active human member), `performer_name` (external service), `part_cost`, `labor_cost` (nonnegative decimal, 2 places), `currency` (uppercase ISO code, defaults RUB), `own_minutes`, `service_minutes`, `is_pinned`.',
            '- `consumption` requires `resource_name`, positive `quantity`, `unit`; `reading` requires `metric_name`, `reading_value` (zero/negative allowed), `unit`. Decimal quantity/readings have up to 4 places.',
            '- PATCH `/{entry}`: REQUIRED `revision` from the latest full GET plus only changed fields. Omitted fields stay unchanged; explicit null clears nullable fields. Equipment cannot be reassigned. A stale revision returns 409: reread and reconcile, never blindly retry.',
            '- DELETE `/{entry}` requires a JSON body with the latest `revision`; deletion is soft and audited. It does not rewind equipment condition, assignments or composition.',
            '- `meta.costs` summarizes source cost ESTIMATES for DONE records; `meta.resources` summarizes resource quantities. Both span all filtered records, not just a page. Estimates do not post money or rewrite Ledger payments. Currencies and units remain separate. Manual minutes do NOT start or duplicate timers. No automatic Eventor event is created.',
            '',
            '### Ledger: project-scoped finance',
            '',
            '- Base: `/api/agent/scopes/{scope}/ledger`. Ledger must be enabled. All requests require `ledger.view`; transaction writes additionally require `ledger.write`; account/category management, transaction deletion/restoration and history require `ledger.manage`. Both token abilities and current scope/project access apply. Creating a record does NOT grant permanent access; removing its creator from the project preserves the record and attribution for the team.',
            '- GET `/options`: permitted projects, accounts with current balances and effective capabilities, categories, currencies. GET `/accounts` and `/transactions`: paginated data; GET `/categories`: category list. Journal filters: `project_id`, `account_id`, `category_id`, `kind`, `status`, `q`, `from`, `to`, `page`, `trash`. Totals span all filtered records, not just a page; currencies remain separate.',
            '- POST `/accounts`: required `project_id`, `title`, `currency`; type `bank|cash|wallet|credit`, decimal `opening_balance`, optional description/color/sort_order. PATCH `/accounts/{account}` requires latest `revision`. Project/currency are immutable; opening balance is locked after any operation. Archive with `is_archived`, do not delete history. Categories use POST/PATCH `/categories[/{category}]`, project/title and kind `income|expense|both`; archive instead of deleting.',
            '- POST `/transactions`: required `account_id`, kind `income|expense|transfer`, positive decimal `amount`, date `occurred_on`, title and UUID `idempotency_key`. Optional `category_id`, Markdown `note_md`, `is_pinned`, status `planned|posted|void`. Transfer requires `target_account_id` in the same scope and currency and write access to BOTH projects; it is ONE atomic operation, never two independent postings. Hidden counterparty details are redacted when reading only one side.',
            '- Supported currencies: RUB, USD, EUR, CNY; no currency exchange or deposit interest. Send decimal money as strings with at most two places. Integer `*_minor` values are returned as strings; use integer/BigInt arithmetic. Only posted, non-deleted operations affect balances.',
            '- Credit accounts require `interest_rate_bps` (integer 0..100000, basis points: 2350 = 23.50% per year) and `interest_start_on` (YYYY-MM-DD, 1900..2100); optional `interest_end_on` is inclusive. Other account types cannot have interest terms. Type and credit terms become immutable after ANY source/incoming transaction, including planned or deleted ones. Opening debt is a NEGATIVE opening balance. Archiving is organizational and does NOT stop accrual; set the last interest day in advance. Variable rate histories and grace periods are not supported.',
            '- Credit interest is a read-only DAILY COMPOUND model, not a bank statement: apply all posted movements of the day, then charge only a negative end-of-day balance, divide the annual rate by 365/366 actual calendar days, round to the nearest minor unit with halves away from zero. No synthetic payments or exploitation expenses are posted. Editing/deleting/restoring a payment recalculates the model.',
            '- Account `balance_minor` retains the all-dated posted BOOK balance excluding modeled interest for compatibility. Use `balance_today_minor` for the calculated balance on `balance_as_of` (today), including `interest_minor`; `principal_today_minor` excludes interest. Future posted movements, planned, void and deleted operations do not affect these current fields. Never sum different currencies.',
            '- GET `/accounts/{account}/statement?month=YYYY-MM` requires current Ledger/project read access; month is 1900-01 through the current month. Returns `{data:{account_id,currency,month,as_of,method,calculated,opening_minor,movement_minor,interest_minor,closing_minor,days:[{date,opening_minor,movement_minor,interest_minor,closing_minor}]}}`. Current month stops at today; previous interest carries into opening. Safe financial range is bounded; a calculation outside it returns 422 instead of silently rounding/overflowing.',
            '- GET `/transactions/{transaction}` returns the complete record. PATCH requires latest `revision` and changed fields only; omitted fields remain intact. Account/target/kind cannot be reassigned. Stale revisions return 409; reread and reconcile. Repeating an identical create with the same UUID returns the original; changing its payload with that UUID returns 409.',
            '- DELETE `/transactions/{transaction}` and POST `/transactions/{transaction}/restore` require JSON body with latest `revision` and manage access to both sides. Soft deletion removes the balance effect but preserves history. GET `/transactions/{transaction}/history` is paginated and requires manage access. Generic contractor traces redact financial data; inspect authorized financial history here.',
            '- One Exploiter entry may have MANY independent Ledger expenses. POST `/exploitation/{entry}` requires latest `entry_revision`, `account_id`, positive decimal string `amount`, `cost_type`, UUID `idempotency_key`, `occurred_on`, status `planned|posted`. Optional `title` (payment annotation, defaults to source title), Markdown `note_md`, `category_id`. Types: `labor|parts|consumables|delivery|service|other|combined`. Requires Equip update/department visibility AND Ledger write/project access. Each expense keeps its own account, currency, amount and date. Different currencies are allowed as separate payments, never added together.',
            '- Retry an identical payment with the SAME UUID to avoid duplication, including after source edits; changing the payload returns 409. A genuinely separate payment needs a NEW UUID. Do not create a replacement for a deleted operation: restore that same operation instead. Update payment amounts, types and notes through normal revision-checked Ledger PATCH; deleting/restoring one payment never alters siblings or source estimates.',
            '- GET `/transactions?exploitation_entry_id={entry}&page=1` lists permitted linked payments, 40 per page; optional `cost_type`, `status`, `trash=1` and other journal filters. Requires source Equip visibility in addition to Ledger/project access. `meta.cost_totals` groups amount_minor by cost_type, currency and planned/posted status across ALL filtered pages; hidden projects, void and trashed payments are excluded. Existing pre-1:N payments with no cost_type appear as `combined`, with original amounts preserved.',
            '- Source GET now includes only `ledger_summary: {linked: boolean}`; financial details must be requested through Ledger. The former `ledger_link` and `ledger_revision` synchronization contract is removed; sending ledger_revision returns 422. Source part_cost/labor_cost are independent estimates and NEVER overwrite recorded payments, including during restoration. Source deletion remains blocked while any financial history exists, even in trash; cancel the source instead.',
            '',
            'Replace `{scope}` and `{task}` with IDs returned by the API:',
            '',
            '- `GET /api/agent/scopes/{scope}/projects`',
            '- `POST /api/agent/scopes/{scope}/projects`',
            '- `GET /api/agent/scopes/{scope}/projects/{project}`',
            '- `PATCH /api/agent/scopes/{scope}/projects/{project}`',
            '- `GET /api/agent/scopes/{scope}/contractors/assignable` — safe assignee options.',
            '## Factor and Contactor',
            '',
            '- Factor base: `/api/agent/scopes/{scope}/facts`. Reads require `fact.view`, writes also require `fact.write`. `fact.reveal` is a separate capability for sensitive values. BOTH token abilities and current account permissions apply; existing keys do not gain new abilities automatically.',
            '- Contactor base: `/api/agent/scopes/{scope}/contacts`. Reads require `contact.view`, writes also require `contact.write`. Contacts are people/organizations, NOT login accounts. Optional `user_id` links an active account in the same scope and never grants login or access.',
            '- Both modules: GET base returns paginated data/links/meta (default 50, per_page max 100); GET /options supplies accessible projects and can_create (contacts also supply account choices). Filters: q, kind, project_id, visibility, pinned, trash; facts add format/expert, contacts add archived. GET /{id} returns can_write and can_manage; use these flags, not role names.',
            '- POST creates. PATCH /{id} accepts partial fields plus REQUIRED revision from the last GET. Omitted fields survive; revision conflicts return 409. Re-read and reconcile, never blindly overwrite. DELETE /{id} and POST /{id}/restore require revision and record management permission; deletion is soft.',
            '- New records default to visibility=private. Existing facts retain scope visibility. Private means creator-only, including against scope owners; scope means current scope members; project requires project_id and current project access. Optional project_id also restricts scope/private records. Explicit project denies and inactive membership override authorship. Only managers may change visibility/project_id/allow_member_editing. Shared content is read-only unless allow_member_editing=true and native write access allows it.',
            '- Fact fields: label, value, format (text|markdown|code|command|number|svg), language, unit, context, kind, display_mode (plain|large|mono|article|snippet|terminal|metric|preview|qr|masked), search_keywords:string[], is_sensitive, is_expert, is_pinned, valid_from, valid_to, sort_order. Values max 200000 characters. Markdown stays Markdown.',
            '- Sensitive values are NEVER present in list/detail/search/link responses (value=null in native list/detail). Only POST /{id}/reveal with fact.reveal returns {data:{value,revision}} with Cache-Control: no-store, private. Reveals are audited without values. Reveal/copy secrets only when explicitly needed; never write them into tasks, notes, logs or metadata. Changing an existing sensitive value or unmasking it also requires fact.reveal.',
            '- Contact fields: name, kind (person|organization), nickname, company, role, phone, email, birthday_on, met_at, met_context, last_contact_at, note_md (Markdown), user_id, is_archived, is_pinned, sort_order. GET /{contact}/notes is chronological, paginated (30); POST /{contact}/notes accepts {title?,content:Markdown,occurred_at?}; DELETE /{contact}/notes/{note} requires native write and author/manager access. Notes inherit contact privacy.',
            '- Links support contact, fact, task, project, event, book, book_page. GET `/api/agent/scopes/{scope}/links?subject_type=contact&subject_id=...` is paginated; GET /links/candidates?type=fact&q=... finds accessible targets. POST /links and DELETE /links/{link} require task.update; reads require task.view. A private source also requires native write access; each target is independently checked. Linking never widens access or exposes fact values/contact details.',
            '- Permalinks: `/factor/{scope}/{fact}`, `/contacts/{scope}/{contact}`. QR is generated locally, never by a remote service.',
            '',
            '- `GET /api/agent/scopes/{scope}/lore/context` — compact current project memory, ordered for agents. Use `?project_id=...` and optional `?as_of=...`.',
            '- `GET /api/agent/scopes/{scope}/lore` — searchable Lore records; filters include `q`, `project_id`, `area_id`, `tag`, `type`, `importance`, `criticality`, and `as_of`.',
            '- `GET /api/agent/scopes/{scope}/lore/{entry}` — one record with its complete immutable revision timeline.',
            '- `POST /api/agent/scopes/{scope}/lore` — create a Lore chain; requires `task.update`.',
            '- Minimal Lore creation payload: `code`, `title`, and Markdown `content`. The API defaults `type=decision`, `importance=mechanic`, `criticality=informational`, `visibility=scope`, and `status=active` when they are omitted.',
            '- `project_id` must be the project ULID returned by the projects endpoint, not its short key. Optional `tags` must be an array of strings.',
            '- `PATCH /api/agent/scopes/{scope}/lore/{entry}` — update Lore metadata. It also accepts `title`, Markdown `content`, and `reason` as a convenient way to edit the currently effective revision in place without finding its revision ID.',
            '- `POST /api/agent/scopes/{scope}/lore/{entry}/revisions` — publish a semantic revision instead of overwriting an earlier decision. Minimal payload is Markdown `content`; omitted `title` is inherited from the current revision and omitted `status` defaults to `active`.',
            '- `PATCH /api/agent/scopes/{scope}/lore/{entry}/revisions/{revision}` — correct the currently effective revision without changing its meaning; only `title`, `content`, and `reason` are editorially mutable.',
            '- `DELETE /api/agent/scopes/{scope}/lore/{entry}` — soft-delete a Lore chain only when `task.delete` is explicitly allowed.',
            '- Lore revision `content` and `reason` are Markdown. Preserve headings, lists, tables, task lists, links, and fenced code blocks; do not flatten them to plain text.',
            '',
            'Minimal Lore create example:',
            '',
            '```json',
            '{"code":"WMS-RESERVE","project_id":"<project-ulid>","title":"Reservation rule","content":"# Rule\\n\\nAvailable quantity excludes reservations.","tags":["wms","reservation"]}',
            '```',
            '',
            'Edit the current revision in place:',
            '',
            '```json',
            '{"content":"# Corrected wording\\n\\nThe meaning is unchanged.","reason":"Editorial correction"}',
            '```',
            '',
            'Publish the next semantic revision:',
            '',
            '```json',
            '{"content":"# New decision\\n\\nThis replaces the earlier rule.","reason":"The business process changed"}',
            '```',
            '',
            'Treat HTTP `422` as payload validation, not throttling: read the JSON `errors` object, fix the named fields, and retry once. Rate limiting is reported only as HTTP `429`.',
            '- `POST /api/agent/scopes/{scope}/links` — link two accessible entities.',
            '- `POST /api/agent/scopes/{scope}/imports/tasker` — idempotent Tasker import; send `dry_run: true` first.',
            '- `POST /api/agent/scopes/{scope}/imports/booker` — idempotent full-book import preserving pages, block types, and block versions; send one book per request and use `dry_run: true` first.',
            '- `GET /api/agent/scopes/{scope}/tasks`',
            '- `POST /api/agent/scopes/{scope}/tasks`',
            '- `GET /api/agent/scopes/{scope}/tasks/search`',
            '- `GET /api/agent/scopes/{scope}/tasks/{task}`',
            '- `PATCH /api/agent/scopes/{scope}/tasks/{task}`',
            '- `GET /api/agent/scopes/{scope}/tasks/{task}/checklist`',
            '- `POST /api/agent/scopes/{scope}/tasks/{task}/checklist`',
            '- `PATCH /api/agent/scopes/{scope}/tasks/{task}/checklist/{item}`',
            '- `GET /api/agent/scopes/{scope}/tasks/{task}/comments`',
            '- `POST /api/agent/scopes/{scope}/tasks/{task}/comments`',
            '- `PATCH /api/agent/scopes/{scope}/tasks/{task}/comments/{comment}`',
            '- `DELETE /api/agent/scopes/{scope}/tasks/{task}/comments/{comment}`',
            '- `GET /api/agent/scopes/{scope}/tasks/{task}/activity`',
            '',
            '## Task discussion and closed tasks',
            '',
            '- Comment POST accepts `content`, optional `parent_id`, and `kind`: `comment` (default), `question`, or `answer`. Questions are top-level; an answer must reply directly to a question. Replies may have only one additional nesting level.',
            '- An answer marks its parent question `is_answered=true`. Removing the last answer reopens the question. PATCH accepts `{"is_answered":true}` or `false` only for questions, by the comment author, task creator, or scope owner. Deleting a root comment also soft-deletes its replies.',
            '- Task lists expose `comments_count` and `unanswered_questions_count`. Discussion mutations require `task.update` in both token abilities and membership capabilities.',
            '- Completed (`done`) tasks freeze their content, assignment, dates, checklist, attachments, tails and links. Only project/department/KPI corrections, board ordering, discussion and status changes remain available. Deleted (`cancelled`) tasks are read-only except board ordering, restoration and authorized permanent deletion.',
            '- To edit frozen fields, first restore the task to an open status in a separate request, only when explicitly authorized by the user. Combining reopening and content edits is rejected with 422. Never reopen a task just to bypass the freeze.',
            '',
            '## Task documents',
            '',
            '- `description` — Markdown describing the task, its context, requirements, and constraints.',
            '- `result` — Markdown describing the verified result of completed work.',
            '- `agent_notes` — Markdown for durable AI findings, important answers, investigation notes, and handoff context. It is a separate task document, not a chat transcript.',
            '- `agent_notes` is accepted by task POST/PATCH endpoints. Send `null` to clear it.',
            '- Keep operational progress, questions, and blockers in task comments. Promote only durable information that should remain visible in the full task editor to `agent_notes`.',
            '',
            'Example:',
            '',
            '```json',
            '{"agent_notes":"## Investigation\\n\\nThe API is healthy. Verified with the production smoke test."}',
            '```',
            '',
            'Only call endpoints allowed by both the token abilities and the membership capabilities. Project restrictions remain in force inside a scope.',
            'Load Lore context before substantial project work. Treat foundational and critical records as mandatory constraints. By default use `current_revision`; request history or `as_of` only when investigating an earlier state. Never rewrite a published semantic decision: create a new revision with its effective date and reason.',
            'Book routes additionally enforce `book_access_mode`: `none`, `projects`, or `all`. Never assume that `book.*` token abilities alone grant access to a book.',
            'Creating facts requires `fact.view` and `fact.write`; creating links requires `task.update` plus native source access. A link payload contains `source_type`, `source_id`, `target_type`, `target_id`, and optional `relation`, `note`, and `meta`.',
            'Tasker imports require both `task.create` and `task.update`, preserve external ULIDs for idempotency, never delete records, and require all-project access when creating projects.',
            'Booker imports require both `book.create` and `book.update`, full book access in the scope, and preserve external ULIDs. They never delete or overwrite an earlier imported entity.',
            '',
            '## Operating rules',
            '',
            '1. Fetch this specification, verify `/api/agent/me`, then load `/api/agent/tasks`.',
            '2. Read the task, its comments and activity before changing it.',
            '3. Make the smallest necessary change and preserve user data.',
            '4. Record meaningful progress or blockers in a task comment. Never claim completion without verification.',
            '5. If access is missing, stop at the boundary and report the exact endpoint and status; do not attempt to bypass it.',
            '6. Do not perform destructive actions unless the assigned task explicitly authorizes them.',
            '',
            'This endpoint is the source of truth. Fetch it again when a workflow or endpoint behaves differently from a cached instruction.',
        ];

        return response(implode("\n", $lines)."\n", 200, [
            'Content-Type' => 'text/markdown; charset=UTF-8',
            'Cache-Control' => 'no-store, private',
        ]);
    }
}
